window.registerCPNSQuestions({"packId":"SKB_PRAKOM_V2","bucket":"SKB_PRAKOM","questions":[{"id":"SKB-PRAKOM-N0001","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Berdasarkan PermenPANRB Nomor 32 Tahun 2020, jenjang Jabatan Fungsional Pranata Komputer kategori keterampilan dari yang terendah hingga tertinggi adalah...","options":["A. Terampil, Mahir, Penyelia","B. Pemula, Terampil, Mahir","C. Pelaksana, Terampil, Penyelia","D. Mahir, Penyelia, Ahli Pertama","E. Terampil, Penyelia, Madya"],"ans":0,"scores":[5,0,0,0,0],"trick":"Keterampilan: T-M-P (Terampil, Mahir, Penyelia). Keahlian: Ahli Pertama, Muda, Madya, Utama.","explanation":"Pasal 5 PermenPANRB 32/2020: kategori keterampilan terdiri atas Terampil, Mahir, dan Penyelia. Kategori keahlian terdiri atas Ahli Pertama, Ahli Muda, Ahli Madya, dan Ahli Utama. 'Pemula' dan 'Pelaksana' tidak dikenal sebagai jenjang JF Prakom."},{"id":"SKB-PRAKOM-N0002","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Jenjang Jabatan Fungsional Pranata Komputer kategori keahlian yang BENAR dari terendah ke tertinggi adalah...","options":["A. Ahli Muda, Ahli Pertama, Ahli Madya, Ahli Utama","B. Ahli Pertama, Ahli Madya, Ahli Muda, Ahli Utama","C. Ahli Dasar, Ahli Muda, Ahli Madya, Ahli Utama","D. Ahli Pertama, Ahli Muda, Ahli Utama, Ahli Madya","E. Ahli Pertama, Ahli Muda, Ahli Madya, Ahli Utama"],"ans":4,"scores":[0,0,0,0,5],"trick":"Urutan keahlian: Pertama → Muda → Madya → Utama (PMMU).","explanation":"Pasal 5 ayat (3) PermenPANRB 32/2020 menyebut urutan Ahli Pertama, Ahli Muda, Ahli Madya, Ahli Utama. Lulusan S1 yang diangkat dari CPNS umumnya memulai dari Ahli Pertama."},{"id":"SKB-PRAKOM-N0003","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Tiga unsur kegiatan Pranata Komputer yang dapat dinilai angka kreditnya menurut PermenPANRB 32/2020 adalah...","options":["A. Perencanaan anggaran; pengadaan barang; audit keuangan","B. Tata kelola dan tata laksana TI; infrastruktur TI; sistem informasi dan multimedia","C. Perakitan perangkat keras; penjualan lisensi; pemasaran digital","D. Administrasi persuratan; protokoler; kerumahtanggaan","E. Pengembangan kurikulum; pembelajaran; penelitian ilmiah"],"ans":1,"scores":[0,5,0,0,0],"trick":"3 unsur: Tata kelola – Infrastruktur – Sistem informasi & multimedia.","explanation":"Pasal 7 ayat (1) PermenPANRB 32/2020 mengelompokkan kegiatan menjadi tata kelola dan tata laksana TI, infrastruktur TI, serta sistem informasi dan multimedia. Opsi lain bukan ruang lingkup JF Prakom."},{"id":"SKB-PRAKOM-N0004","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Menurut UU Nomor 20 Tahun 2023 tentang Aparatur Sipil Negara, ASN terdiri atas...","options":["A. PNS, PPPK, dan tenaga honorer yang sudah bekerja lebih dari lima tahun","B. PNS dan prajurit TNI/anggota Polri yang bertugas di instansi sipil","C. PNS dan PPPK","D. Pejabat negara hasil pemilu dan PNS yang menjabat di lembaga tinggi","E. CPNS yang sedang masa percobaan dan PNS yang telah diangkat penuh"],"ans":2,"scores":[0,0,5,0,0],"trick":"ASN = PNS + PPPK (honorer tidak termasuk).","explanation":"UU 20/2023 menegaskan ASN terdiri atas PNS dan PPPK (Pegawai Pemerintah dengan Perjanjian Kerja). Tenaga honorer bukan kategori ASN dan ditata sesuai ketentuan peralihan UU tersebut."},{"id":"SKB-PRAKOM-N0005","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Berdasarkan UU Nomor 20 Tahun 2023, jabatan ASN secara garis besar dibedakan menjadi...","options":["A. Jabatan struktural, jabatan fungsional, dan jabatan honorer daerah","B. Jabatan politik, jabatan karier, dan jabatan kontrak berjangka","C. Jabatan eselon, jabatan pelaksana, dan jabatan khusus lembaga","D. Jabatan manajerial dan jabatan nonmanajerial","E. Jabatan teknis, jabatan administratif, dan jabatan kehormatan"],"ans":3,"scores":[0,0,0,5,0],"trick":"Jabatan ASN: manajerial (JPT & administrasi) vs nonmanajerial (fungsional/pelaksana).","explanation":"UU 20/2023 membagi jabatan ASN menjadi jabatan manajerial (pimpinan tinggi dan jabatan administrasi/manajerial) dan jabatan nonmanajerial (antara lain jabatan fungsional). Opsi yang memuat 'honorer', 'politik', atau 'kontrak' keliru."},{"id":"SKB-PRAKOM-N0006","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Nilai dasar (core values) ASN BerAKHLAK yang berkaitan dengan sikap 'menjaga nama baik sesama ASN, pimpinan, instansi, dan negara' adalah...","options":["A. Harmonis","B. Akuntabel","C. Adaptif","D. Kompeten","E. Loyal"],"ans":4,"scores":[0,0,0,0,5],"trick":"BerAKHLAK: Berorientasi pelayanan, Akuntabel, Kompeten, Harmonis, Loyal, Adaptif, Kolaboratif.","explanation":"Dalam panduan perilaku BerAKHLAK, nilai Loyal mencakup memegang teguh ideologi Pancasila dan UUD 1945, setia pada NKRI, menjaga nama baik sesama ASN, pimpinan, instansi, dan negara, serta menjaga rahasia jabatan dan negara."},{"id":"SKB-PRAKOM-N0007","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Seorang Pranata Komputer rutin memperbarui keahlian dengan mengikuti pelatihan keamanan siber dan membagikan ilmunya kepada rekan. Perilaku ini paling sesuai dengan nilai BerAKHLAK...","options":["A. Kompeten","B. Loyal","C. Harmonis","D. Berorientasi Pelayanan","E. Adaptif"],"ans":0,"scores":[5,0,0,0,0],"trick":"Kompeten = meningkatkan kompetensi diri + membantu orang lain belajar + melaksanakan tugas dengan kualitas terbaik.","explanation":"Panduan perilaku Kompeten meliputi meningkatkan kompetensi diri untuk menjawab tantangan yang selalu berubah, membantu orang lain belajar, dan melaksanakan tugas dengan kualitas terbaik."},{"id":"SKB-PRAKOM-N0008","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Peraturan yang mengatur tentang penilaian kinerja PNS yang berbasis Sasaran Kinerja Pegawai (SKP) dan perilaku kerja adalah...","options":["A. PP Nomor 94 Tahun 2021","B. PP Nomor 30 Tahun 2019","C. PP Nomor 53 Tahun 2010","D. PP Nomor 17 Tahun 2020","E. PP Nomor 71 Tahun 2019"],"ans":1,"scores":[0,5,0,0,0],"trick":"30/2019 = kinerja (SKP); 94/2021 = disiplin; 17/2020 = manajemen PNS; 71/2019 = PSTE.","explanation":"PP 30/2019 mengatur Penilaian Kinerja PNS. PP 94/2021 mengatur Disiplin PNS (menggantikan PP 53/2010). PP 17/2020 mengubah PP 11/2017 tentang Manajemen PNS. PP 71/2019 tentang Penyelenggaraan Sistem dan Transaksi Elektronik."},{"id":"SKB-PRAKOM-N0009","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Peraturan Pemerintah yang saat ini menjadi dasar pengaturan disiplin PNS, menggantikan PP Nomor 53 Tahun 2010, adalah...","options":["A. PP Nomor 30 Tahun 2019","B. PP Nomor 11 Tahun 2017","C. PP Nomor 94 Tahun 2021","D. PP Nomor 17 Tahun 2020","E. PP Nomor 45 Tahun 1990"],"ans":2,"scores":[0,0,5,0,0],"trick":"Disiplin PNS terbaru = PP 94/2021.","explanation":"PP 94/2021 tentang Disiplin PNS mencabut PP 53/2010. Hukuman disiplin dibagi ringan, sedang, dan berat."},{"id":"SKB-PRAKOM-N0010","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Berdasarkan PP Nomor 94 Tahun 2021, jenis hukuman disiplin PNS dikelompokkan menjadi...","options":["A. Peringatan, teguran, dan pemecatan","B. Hukuman administratif dan hukuman pidana","C. Hukuman ringan dan berat saja","D. Hukuman disiplin ringan, sedang, dan berat","E. Hukuman moral, material, dan jabatan"],"ans":3,"scores":[0,0,0,5,0],"trick":"Tingkat hukuman: ringan – sedang – berat.","explanation":"PP 94/2021 membagi tingkat hukuman disiplin menjadi ringan (teguran lisan, tertulis, pernyataan tidak puas secara tertulis), sedang (pemotongan tunjangan kinerja), dan berat (penurunan jabatan, pembebasan, pemberhentian)."},{"id":"SKB-PRAKOM-N0011","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Pak Rudi, Pranata Komputer Ahli Muda, ditawari laptop oleh vendor yang sedang mengikuti tender di dinasnya. Tindakan yang tepat adalah...","options":["A. Menerima karena laptop akan dipakai untuk keperluan kantor sehari-hari","B. Menerima lalu menyimpannya tanpa memberi tahu atasan agar tidak ada masalah","C. Menolak dan melaporkannya sebagai gratifikasi sesuai ketentuan","D. Menerima dan memberi catatan khusus pada dokumen evaluasi tender vendor itu","E. Menerima setelah masa tender selesai tanpa perlu melapor kepada siapa pun"],"ans":2,"scores":[0,0,5,0,0],"trick":"Gratifikasi terkait jabatan: tolak atau lapor ≤30 hari kerja.","explanation":"Pemberian dari pihak yang berkepentingan dengan jabatan termasuk gratifikasi dan berpotensi konflik kepentingan. ASN wajib menolak, atau jika sudah menerima wajib melapor kepada KPK/UPG dalam 30 hari kerja."},{"id":"SKB-PRAKOM-N0012","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Menurut Perpres Nomor 95 Tahun 2018, SPBE adalah...","options":["A. Sistem pengadaan barang/jasa pemerintah yang seluruhnya dilakukan secara elektronik","B. Program pembangunan jaringan internet di seluruh wilayah perbatasan dan terluar","C. Pelaksanaan pemilihan umum dengan pemungutan suara secara elektronik penuh","D. Penyelenggaraan pemerintahan yang memanfaatkan TIK untuk memberi layanan kepada pengguna SPBE","E. Penggantian pegawai pemerintah dengan sistem otomatis berbasis kecerdasan buatan"],"ans":3,"scores":[0,0,0,5,0],"trick":"SPBE = pemerintahan memanfaatkan TIK untuk layanan; e-procurement hanya salah satu layanan.","explanation":"Perpres 95/2018 mendefinisikan SPBE sebagai penyelenggaraan pemerintahan yang memanfaatkan TIK untuk memberikan layanan kepada Pengguna SPBE."},{"id":"SKB-PRAKOM-N0013","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Dalam Perpres 95/2018, infrastruktur SPBE terdiri atas...","options":["A. Pusat Data, Jaringan Intra, dan Sistem Penghubung Layanan","B. Aplikasi Umum, Aplikasi Khusus, dan Portal","C. Server, Router, dan Switch saja","D. Pusat Data, Aplikasi Umum, dan Jaringan Intra","E. Sistem Penghubung Layanan, Portal, dan Aplikasi Khusus"],"ans":0,"scores":[5,0,0,0,0],"trick":"Infrastruktur SPBE = Pusat Data + Jaringan Intra + SPL.","explanation":"Infrastruktur SPBE nasional meliputi Pusat Data, Jaringan Intra, dan Sistem Penghubung Layanan Pemerintah. Aplikasi umum dan khusus termasuk domain aplikasi SPBE, bukan infrastruktur."},{"id":"SKB-PRAKOM-N0014","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Aplikasi SPBE yang digunakan bersama lintas instansi pusat dan/atau pemerintah daerah, memiliki standar sama, dan dibangun/dikembangkan oleh instansi pusat/pemerintah daerah tertentu disebut...","options":["A. Aplikasi Khusus","B. Aplikasi Umum","C. Aplikasi Sektoral","D. Aplikasi Legacy","E. Aplikasi Pihak Ketiga"],"ans":1,"scores":[0,5,0,0,0],"trick":"Umum = dipakai bersama lintas instansi; Khusus = hanya untuk 1 instansi/fungsi tertentu.","explanation":"Aplikasi Umum adalah Aplikasi SPBE yang sama, standar, dan digunakan bersama lintas instansi. Aplikasi Khusus dibangun, dikembangkan, digunakan, dan dikelola oleh instansi tertentu untuk memenuhi kebutuhan khusus yang spesifik."},{"id":"SKB-PRAKOM-N0015","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Domain yang dinilai dalam Indeks SPBE berdasarkan PermenPANRB Nomor 59 Tahun 2020 meliputi...","options":["A. Perencanaan, Pengadaan, Pembangunan, dan Pemeliharaan","B. Infrastruktur, Aplikasi, Data, dan Keamanan","C. Input, Proses, Output, dan Outcome","D. Teknis, Hukum, Anggaran, dan SDM","E. Kebijakan, Tata Kelola, Manajemen, dan Layanan SPBE"],"ans":4,"scores":[0,0,0,0,5],"trick":"Indeks SPBE: Kebijakan – Tata Kelola – Manajemen – Layanan.","explanation":"PermenPANRB 59/2020 tentang Pemantauan dan Evaluasi SPBE mengukur empat domain: kebijakan internal, tata kelola, manajemen, dan layanan SPBE. Opsi B memuat domain arsitektur, bukan domain indeks."},{"id":"SKB-PRAKOM-N0016","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Arsitektur SPBE Nasional (Perpres 132/2022) memuat domain berikut, KECUALI...","options":["A. Arsitektur Proses Bisnis","B. Arsitektur Data dan Informasi","C. Arsitektur Keamanan SPBE","D. Arsitektur Layanan SPBE","E. Arsitektur Anggaran dan Pengadaan"],"ans":4,"scores":[0,0,0,0,5],"trick":"6 domain: Proses Bisnis, Data & Informasi, Infrastruktur, Aplikasi, Keamanan, Layanan.","explanation":"Domain arsitektur SPBE: proses bisnis, data dan informasi, infrastruktur SPBE, aplikasi SPBE, keamanan SPBE, dan layanan SPBE. Anggaran dan pengadaan bukan domain arsitektur."},{"id":"SKB-PRAKOM-N0017","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Prinsip Satu Data Indonesia (Perpres 39/2019) yang menjamin data dapat dibagipakaikan antarinstansi adalah...","options":["A. Interoperabilitas data","B. Data cadangan (backup)","C. Enkripsi total","D. Sentralisasi server","E. Digitalisasi arsip"],"ans":0,"scores":[5,0,0,0,0],"trick":"SDI: standar data, metadata baku, interoperabilitas, kode referensi & data induk.","explanation":"Empat prinsip SDI: standar data, metadata baku, interoperabilitas data, serta kode referensi dan/atau data induk. Interoperabilitas memungkinkan pemakaian bersama data antarinstansi."},{"id":"SKB-PRAKOM-N0018","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Pada UU Nomor 27 Tahun 2022 tentang Pelindungan Data Pribadi, yang termasuk data pribadi bersifat spesifik adalah...","options":["A. Nama lengkap, jenis kelamin, dan kewarganegaraan","B. Alamat surel dan nomor telepon","C. Data kesehatan, biometrik, genetika, dan data anak","D. Agama dan tempat lahir saja","E. Foto profil media sosial"],"ans":2,"scores":[0,0,5,0,0],"trick":"Spesifik: kesehatan, biometrik, genetika, catatan kejahatan, anak, keuangan pribadi.","explanation":"UU PDP membagi data pribadi menjadi spesifik (kesehatan, biometrik, genetika, catatan kejahatan, data anak, data keuangan pribadi, dan data lain sesuai ketentuan) dan umum (nama, jenis kelamin, kewarganegaraan, agama, status perkawinan, dan data yang dikombinasikan untuk identifikasi)."},{"id":"SKB-PRAKOM-N0019","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Menurut UU PDP, pihak yang menentukan tujuan dan melakukan kendali pemrosesan data pribadi disebut...","options":["A. Prosesor Data Pribadi","B. Subjek Data Pribadi","C. Pejabat Pengelola Informasi","D. Pengendali Data Pribadi","E. Administrator Basis Data"],"ans":3,"scores":[0,0,0,5,0],"trick":"Pengendali = penentu tujuan & kendali; Prosesor = memproses atas nama pengendali; Subjek = pemilik data.","explanation":"UU PDP mengenal Subjek Data Pribadi (orang yang melekat data), Pengendali (menentukan tujuan dan kendali), dan Prosesor (memproses atas nama pengendali)."},{"id":"SKB-PRAKOM-N0020","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Jika terjadi kegagalan pelindungan data pribadi, Pengendali Data wajib menyampaikan pemberitahuan tertulis kepada subjek data dan lembaga paling lambat...","options":["A. 1 x 24 jam","B. 3 x 24 jam","C. 7 x 24 jam","D. 14 hari kerja","E. 30 hari kalender"],"ans":1,"scores":[0,5,0,0,0],"trick":"Notifikasi kebocoran data: 3×24 jam.","explanation":"Pasal 46 UU 27/2022 mewajibkan pemberitahuan tertulis paling lambat 3 × 24 jam setelah kegagalan pelindungan data pribadi diketahui."},{"id":"SKB-PRAKOM-N0021","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"UU ITE yang berlaku saat ini merupakan perubahan kedua dari UU Nomor 11 Tahun 2008, yaitu...","options":["A. UU Nomor 19 Tahun 2016","B. UU Nomor 1 Tahun 2024","C. UU Nomor 27 Tahun 2022","D. UU Nomor 14 Tahun 2008","E. UU Nomor 20 Tahun 2023"],"ans":1,"scores":[0,5,0,0,0],"trick":"ITE: 11/2008 → 19/2016 (perubahan pertama) → 1/2024 (perubahan kedua).","explanation":"UU 11/2008 diubah dengan UU 19/2016 (perubahan pertama) dan UU 1/2024 (perubahan kedua)."},{"id":"SKB-PRAKOM-N0022","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Strategi Keamanan Siber Nasional dan Manajemen Krisis Siber diatur dalam...","options":["A. Perpres Nomor 95 Tahun 2018","B. Perpres Nomor 39 Tahun 2019","C. PermenPANRB Nomor 59 Tahun 2020","D. Perpres Nomor 47 Tahun 2023","E. PP Nomor 94 Tahun 2021"],"ans":3,"scores":[0,0,0,5,0],"trick":"Siber nasional = Perpres 47/2023 (BSSN).","explanation":"Perpres 47/2023 menetapkan Strategi Keamanan Siber Nasional dan Manajemen Krisis Siber. Perpres 95/2018 adalah SPBE, Perpres 39/2019 adalah Satu Data Indonesia."},{"id":"SKB-PRAKOM-N0023","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Instansi pemerintah yang berperan menerbitkan sertifikat elektronik dan menjadi otoritas sertifikat digital (BSrE) bagi instansi pemerintah adalah...","options":["A. Badan Pusat Statistik","B. Lembaga Sandi Telekomunikasi Swasta","C. Badan Informasi Geospasial","D. Ombudsman RI","E. Badan Siber dan Sandi Negara (BSSN)"],"ans":4,"scores":[0,0,0,0,5],"trick":"BSrE = Balai Sertifikasi Elektronik di bawah BSSN.","explanation":"BSrE (Balai Sertifikasi Elektronik) merupakan penyelenggara sertifikasi elektronik di bawah BSSN yang melayani tanda tangan elektronik tersertifikasi bagi instansi pemerintah."},{"id":"SKB-PRAKOM-N0024","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Dinas Kominfo Provinsi A akan membangun aplikasi layanan perizinan. Langkah awal paling sesuai prinsip SPBE adalah...","options":["A. Langsung menunjuk vendor pengembang tanpa kajian kebutuhan dan integrasi lebih dulu","B. Membuat aplikasi sendiri tanpa memperhatikan keterhubungan dengan sistem lain","C. Memeriksa arsitektur SPBE dan aplikasi umum yang tersedia agar tidak duplikat","D. Menunda sampai ada aplikasi sejenis dari kabupaten/kota yang sudah rampung","E. Membeli perangkat keras berspesifikasi tinggi sebelum kebutuhan fungsional jelas"],"ans":2,"scores":[0,0,5,0,0],"trick":"Prinsip SPBE: hindari duplikasi, bangun sesuai arsitektur & berbagi pakai.","explanation":"SPBE menekankan keterpaduan dan efisiensi: aplikasi baru harus mengacu arsitektur SPBE dan memanfaatkan aplikasi umum/berbagi pakai yang ada untuk mencegah duplikasi dan pemborosan anggaran."},{"id":"SKB-PRAKOM-N0025","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Pertukaran data antarsistem yang berbeda platform dapat difasilitasi oleh Sistem Penghubung Layanan Pemerintah. Peran utamanya adalah...","options":["A. Menyediakan integrasi dan interoperabilitas layanan antarinstansi","B. Menyimpan seluruh data instansi di satu basis data","C. Menggantikan peran jaringan intra pemerintah","D. Menjalankan aplikasi khusus tiap instansi","E. Menghapus kebutuhan standar data"],"ans":0,"scores":[5,0,0,0,0],"trick":"SPL = jembatan integrasi (API gateway/enterprise service bus) antar layanan.","explanation":"Sistem Penghubung Layanan (SPL) berfungsi menghubungkan layanan SPBE antarinstansi sehingga data dan layanan dapat dipertukarkan secara terintegrasi dan terstandar, bukan menyimpan semua data di satu tempat."},{"id":"SKB-PRAKOM-N0026","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Dalam COBIT 2019, domain yang termasuk dalam area GOVERNANCE (bukan management) adalah...","options":["A. APO (Align, Plan and Organize)","B. BAI (Build, Acquire and Implement)","C. DSS (Deliver, Service and Support)","D. MEA (Monitor, Evaluate and Assess)","E. EDM (Evaluate, Direct and Monitor)"],"ans":4,"scores":[0,0,0,0,5],"trick":"Governance = EDM saja; management = APO, BAI, DSS, MEA.","explanation":"COBIT 2019 memiliki satu domain governance (EDM) dan empat domain management (APO, BAI, DSS, MEA), total 40 tujuan tata kelola dan manajemen."},{"id":"SKB-PRAKOM-N0027","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Dalam COBIT 2019, penanganan insiden, permintaan layanan, dan manajemen masalah termasuk domain...","options":["A. APO (Align, Plan and Organize)","B. BAI (Build, Acquire and Implement)","C. DSS (Deliver, Service and Support)","D. MEA (Monitor, Evaluate and Assess)","E. EDM (Evaluate, Direct and Monitor)"],"ans":2,"scores":[0,0,5,0,0],"trick":"DSS = operasi harian: insiden, masalah, kontinuitas, keamanan operasional.","explanation":"DSS mencakup DSS02 (manajemen permintaan layanan dan insiden) dan DSS03 (manajemen masalah). APO fokus strategi dan perencanaan, BAI fokus pembangunan/perubahan."},{"id":"SKB-PRAKOM-N0028","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Empat dimensi manajemen layanan pada ITIL 4 adalah...","options":["A. Perencanaan, desain, transisi, operasi, dan peningkatan layanan berkelanjutan","B. Organisasi & manusia; informasi & teknologi; mitra & pemasok; aliran nilai & proses","C. Orang, proses, produk, dan mitra yang dikelola melalui siklus hidup layanan","D. Strategi, desain, transisi, operasi, dan peningkatan berkelanjutan layanan","E. Kebijakan, prosedur, standar, dan pedoman yang disahkan pimpinan organisasi"],"ans":1,"scores":[0,5,0,0,0],"trick":"4 dimensi ITIL 4: O&P, I&T, P&S, VS&P.","explanation":"Empat dimensi ITIL 4: organizations and people; information and technology; partners and suppliers; value streams and processes. Opsi lain adalah siklus hidup ITIL v3 atau konsep umum."},{"id":"SKB-PRAKOM-N0029","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Aktivitas Service Value Chain ITIL 4 yang berfokus pada memahami kebutuhan pemangku kepentingan dan mengelola hubungan adalah...","options":["A. Engage","B. Plan","C. Obtain/Build","D. Deliver and Support","E. Improve"],"ans":0,"scores":[5,0,0,0,0],"trick":"SVC 6 aktivitas: Plan, Improve, Engage, Design & Transition, Obtain/Build, Deliver & Support.","explanation":"Engage menyediakan pemahaman baik terhadap kebutuhan pemangku kepentingan, transparansi, dan hubungan baik dengan semua pemangku kepentingan."},{"id":"SKB-PRAKOM-N0030","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Menurut ITIL, manajemen masalah (problem management) berbeda dengan manajemen insiden karena problem management berfokus pada...","options":["A. Memulihkan layanan secepat mungkin","B. Menerima permintaan layanan standar dari pengguna","C. Mengubah kontrak dengan pemasok","D. Mencari dan menghilangkan akar penyebab agar insiden tidak berulang","E. Menambah kapasitas server"],"ans":3,"scores":[0,0,0,5,0],"trick":"Insiden = pulihkan cepat (workaround); Masalah = akar penyebab (RCA).","explanation":"Incident management bertujuan meminimalkan dampak insiden dan memulihkan layanan normal. Problem management mengidentifikasi akar penyebab dan mengelola known error serta workaround."},{"id":"SKB-PRAKOM-N0031","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Layanan e-office memiliki RTO 4 jam dan RPO 15 menit. Artinya...","options":["A. Data boleh hilang hingga 4 jam, sedangkan layanan harus pulih dalam 15 menit","B. Layanan pulih paling lama 4 jam; data hilang paling banyak 15 menit terakhir","C. Layanan harus pulih dalam 15 menit dan data tidak boleh hilang sama sekali","D. Backup dibuat tiap 4 jam dan proses pemulihan data memakan waktu 15 menit","E. Layanan boleh berhenti 15 menit di setiap rentang waktu 4 jam operasional"],"ans":1,"scores":[0,5,0,0,0],"trick":"RTO = waktu pemulihan layanan; RPO = batas kehilangan data (interval backup).","explanation":"RTO adalah batas waktu pemulihan layanan; RPO adalah jumlah kehilangan data yang dapat ditoleransi, diukur dalam waktu. RPO 15 menit berarti replikasi/backup minimal tiap 15 menit."},{"id":"SKB-PRAKOM-N0032","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Standar internasional untuk Sistem Manajemen Keamanan Informasi (SMKI) adalah...","options":["A. ISO/IEC 20000-1","B. ISO 22301","C. ISO/IEC 38500","D. ISO 9001","E. ISO/IEC 27001"],"ans":4,"scores":[0,0,0,0,5],"trick":"27001=keamanan informasi; 20000=layanan TI; 22301=kontinuitas bisnis; 38500=tata kelola TI; 9001=mutu.","explanation":"ISO/IEC 27001 menetapkan persyaratan SMKI. ISO 20000-1 untuk manajemen layanan, ISO 22301 untuk kelangsungan bisnis, ISO 38500 untuk tata kelola TI, ISO 9001 untuk manajemen mutu."},{"id":"SKB-PRAKOM-N0033","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Versi ISO/IEC 27001:2022 mengelompokkan kontrol Annex A (93 kontrol) dalam empat tema, yaitu...","options":["A. Kebijakan, prosedur, standar, dan pedoman","B. Pencegahan, deteksi, koreksi, dan pemulihan","C. Organisasi, orang, fisik, dan teknologi","D. Teknis, administratif, hukum, dan fisik","E. Kerahasiaan, integritas, ketersediaan, dan akuntabilitas"],"ans":2,"scores":[0,0,5,0,0],"trick":"27001:2022 → 4 tema: Organizational, People, Physical, Technological.","explanation":"Revisi 2022 menyederhanakan 114 kontrol (14 domain) pada versi 2013 menjadi 93 kontrol dalam 4 tema: organisasi (37), orang (8), fisik (14), teknologi (34)."},{"id":"SKB-PRAKOM-N0034","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Fase TOGAF ADM yang berfokus pada pengembangan arsitektur data dan aplikasi (Information Systems Architecture) adalah fase...","options":["A. C","B. A","C. B","D. D","E. F"],"ans":0,"scores":[5,0,0,0,0],"trick":"ADM: Prelim, A Vision, B Business, C Information Systems, D Technology, E Opp&Sol, F Migration, G Impl Gov, H Change.","explanation":"Fase A visi arsitektur, B arsitektur bisnis, C arsitektur sistem informasi (data & aplikasi), D arsitektur teknologi, E peluang & solusi, F perencanaan migrasi, G tata kelola implementasi, H manajemen perubahan."},{"id":"SKB-PRAKOM-N0035","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Seorang Pranata Komputer ditugaskan menilai ancaman dan dampak terhadap aset informasi dinas. Standar yang paling relevan sebagai kerangka umum manajemen risiko adalah...","options":["A. ISO 14001","B. ISO 26000","C. ISO 45001","D. ISO 31000","E. ISO 50001"],"ans":3,"scores":[0,0,0,5,0],"trick":"31000 = manajemen risiko; 27005 = risiko keamanan informasi.","explanation":"ISO 31000 memberikan prinsip dan pedoman manajemen risiko. ISO 27005 khusus risiko keamanan informasi. ISO 14001 lingkungan, 45001 K3, 50001 energi."},{"id":"SKB-PRAKOM-N0036","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Pada pengukuran layanan, perjanjian antara penyedia layanan TI dengan pelanggan yang memuat target tingkat layanan (misalnya ketersediaan 99,5%) disebut...","options":["A. Service Level Agreement (SLA)","B. Operational Level Agreement (OLA)","C. Underpinning Contract (UC)","D. Non-Disclosure Agreement (NDA)","E. Memorandum of Understanding (MoU)"],"ans":0,"scores":[5,0,0,0,0],"trick":"SLA=dengan pelanggan; OLA=antartim internal; UC=dengan pemasok eksternal.","explanation":"SLA mengikat penyedia layanan dan pelanggan. OLA adalah kesepakatan antartim internal. UC adalah kontrak penyedia layanan dengan pemasok pihak ketiga."},{"id":"SKB-PRAKOM-N0037","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Basis data yang menyimpan item konfigurasi (CI) beserta hubungan antar-CI pada manajemen layanan TI disebut...","options":["A. Data warehouse institusi","B. Knowledge base pengguna akhir","C. Log server terpusat","D. CMDB","E. Directory service terpusat"],"ans":3,"scores":[0,0,0,5,0],"trick":"CMDB = CI + relasi (analisis dampak perubahan).","explanation":"CMDB (Configuration Management Database) menyimpan CI seperti server, aplikasi, dan jaringan beserta hubungannya sehingga memudahkan analisis dampak perubahan dan penelusuran insiden."},{"id":"SKB-PRAKOM-N0038","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"DR drill menunjukkan pemulihan layanan memakan 9 jam, padahal RTO 4 jam. Tindak lanjut terbaik...","options":["A. Mengubah target RTO menjadi 9 jam tanpa kajian risiko bisnis terlebih dahulu","B. Menghentikan program DR drill karena hasilnya tidak memenuhi target yang ditetapkan","C. Tidak mencantumkan hasil drill dalam laporan agar tidak menjadi temuan audit","D. Menambah bandwidth jaringan secara langsung tanpa menganalisis penyebab keterlambatan","E. Analisis akar penyebab, perbaiki prosedur/arsitektur, lalu uji ulang"],"ans":4,"scores":[0,0,0,0,5],"trick":"Drill gagal → RCA → perbaikan → uji ulang (PDCA).","explanation":"Tujuan DR drill adalah menemukan kelemahan. Respons tepat: analisis akar penyebab, perbaikan, pengujian ulang. Menurunkan target tanpa kajian tidak menyelesaikan risiko."},{"id":"SKB-PRAKOM-N0039","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Regulasi JF Prakom & Manajemen ASN","q":"Pranata Komputer Ahli Pertama ditugaskan menyusun dokumen kebutuhan sistem informasi OPD. Kegiatan tersebut termasuk unsur...","options":["A. Infrastruktur TI","B. Penunjang tugas non-JF","C. Sistem informasi dan multimedia","D. Pengembangan profesi (pendidikan)","E. Tata kelola kepegawaian"],"ans":2,"scores":[0,0,5,0,0],"trick":"Rancang/bangun aplikasi = unsur Sistem Informasi & Multimedia; jaringan/server = Infrastruktur.","explanation":"Analisis kebutuhan, perancangan, dan pengembangan sistem informasi masuk unsur sistem informasi dan multimedia. Pengelolaan jaringan, server, dan pusat data masuk unsur infrastruktur TI."},{"id":"SKB-PRAKOM-N0040","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Prinsip meminimalkan duplikasi aplikasi dan mendorong penggunaan bersama dalam SPBE disebut...","options":["A. Segmentasi sistem antarinstansi","B. Berbagi pakai","C. Desentralisasi penuh seluruh layanan","D. Privatisasi layanan pemerintah","E. Kemandirian teknologi tiap OPD"],"ans":1,"scores":[0,5,0,0,0],"trick":"SPBE: keterpaduan & berbagi pakai (efisiensi).","explanation":"Perpres 95/2018 menekankan keterpaduan dan berbagi pakai infrastruktur, data, dan aplikasi agar efisien dan interoperabel."},{"id":"SKB-PRAKOM-N0041","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Layanan SPBE dikelompokkan menjadi...","options":["A. Layanan internal instansi dan layanan eksternal yang dikelola pihak swasta","B. Layanan antarpemerintah (G2G) dan layanan antarbisnis (B2B) saja","C. Layanan administrasi pemerintahan dan layanan publik berbasis elektronik","D. Layanan intranet pemerintah dan layanan ekstranet khusus mitra bisnis","E. Layanan transmisi data dan layanan telepon suara pada jaringan pemerintah"],"ans":2,"scores":[0,0,5,0,0],"trick":"Layanan SPBE: administrasi pemerintahan + layanan publik.","explanation":"Perpres 95/2018 membedakan Layanan Administrasi Pemerintahan Berbasis Elektronik (kepegawaian, keuangan, dll.) dan Layanan Publik Berbasis Elektronik (perizinan, kependudukan, dll.)."},{"id":"SKB-PRAKOM-N0042","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Berdasarkan ISO/IEC 38500, tugas utama pimpinan dalam tata kelola TI direpresentasikan oleh siklus...","options":["A. Plan, Do, Check, Act","B. Evaluate, Direct, Monitor","C. Identify, Protect, Detect","D. Design, Build, Run","E. Plan, Build, Run, Monitor"],"ans":1,"scores":[0,5,0,0,0],"trick":"ISO 38500 & COBIT EDM = Evaluate–Direct–Monitor.","explanation":"Model tata kelola ISO 38500 menempatkan pimpinan pada tiga tugas: mengevaluasi, mengarahkan, dan memantau penggunaan TI. Ini selaras dengan domain EDM pada COBIT."},{"id":"SKB-PRAKOM-N0043","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Tata Kelola & Manajemen Layanan TI","q":"Prinsip pemandu ITIL 4 'Start Where You Are' berarti...","options":["A. Selalu membangun sistem baru dari awal agar bebas dari warisan masalah lama","B. Menunda perubahan hingga seluruh kebutuhan pemangku kepentingan terdokumentasi","C. Mengganti seluruh tim internal dengan konsultan eksternal yang berpengalaman","D. Menilai kondisi saat ini dan memakai ulang aset yang sudah ada","E. Menghindari pengukuran kondisi awal supaya perbaikan tidak terkesan menyalahkan"],"ans":3,"scores":[0,0,0,5,0],"trick":"7 prinsip: Value, Start where you are, Iterative, Collaborate, Holistic, Simple, Optimize&automate.","explanation":"Prinsip ini menyarankan menilai kondisi saat ini dan menggunakan ulang layanan, proses, dan kemampuan yang bermanfaat sebelum membuat yang baru."},{"id":"SKB-PRAKOM-N0044","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"SPBE & Kebijakan Digital Nasional","q":"Data penduduk dari dua OPD provinsi berbeda angkanya. Solusi tata kelola data paling tepat...","options":["A. Memerintahkan salah satu OPD menghapus datanya agar hanya ada satu versi","B. Membuat basis data baru terpisah untuk masing-masing OPD yang berselisih","C. Menunggu data nasional dari pusat sempurna sebelum melakukan tindakan apa pun","D. Mengunci akses ke data kedua OPD sampai ada instruksi dari pimpinan daerah","E. Menetapkan data induk, walidata, dan metadata baku lewat forum Satu Data"],"ans":4,"scores":[0,0,0,0,5],"trick":"SDI: walidata, produsen data, data induk, metadata baku.","explanation":"Perpres 39/2019 mengatur forum Satu Data, Walidata (pengelola data), dan data induk. Konsistensi diperoleh dengan standar data dan metadata yang disepakati, bukan menghapus data sepihak."},{"id":"SKB-PRAKOM-N0045","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Tabel PEGAWAI\nid | nama  | dept | gaji\n1  | Ani   | TI   | 8\n2  | Budi  | TI   | 6\n3  | Citra | HR   | 7\n4  | Dedi  | HR   | NULL\n5  | Eka   | KEU  | 9\n\nHasil dari SELECT AVG(gaji) FROM PEGAWAI; adalah...","options":["A. 7,5 karena nilai NULL diabaikan dalam perhitungan rata-rata","B. 6,0 karena NULL dihitung sebagai nol dan dibagi lima baris","C. NULL karena ada satu nilai kosong pada kolom gaji","D. 7,5 karena NULL diganti nilai rata-rata sebelum dihitung","E. 6,0 karena fungsi AVG hanya menghitung baris pertama"],"ans":0,"scores":[5,0,0,0,0],"trick":"Fungsi agregat (AVG, SUM, MIN, MAX, COUNT(kolom)) mengabaikan NULL.","explanation":"AVG menghitung (8+6+7+9)/4 = 7,5 karena baris dengan gaji NULL tidak ikut dihitung. COUNT(*) menghitung semua baris, COUNT(gaji) hanya yang tidak NULL."},{"id":"SKB-PRAKOM-N0046","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Tabel PEGAWAI\nid | nama  | dept | gaji\n1  | Ani   | TI   | 8\n2  | Budi  | TI   | 6\n3  | Citra | HR   | 7\n4  | Dedi  | HR   | NULL\n5  | Eka   | KEU  | 9\n\nSELECT COUNT(*), COUNT(gaji) FROM PEGAWAI; menghasilkan...","options":["A. 5 dan 5","B. 4 dan 4","C. 4 dan 5","D. 5 dan 3","E. 5 dan 4"],"ans":4,"scores":[0,0,0,0,5],"trick":"COUNT(*) = semua baris; COUNT(kolom) = baris non-NULL.","explanation":"Ada 5 baris, tetapi satu baris (Dedi) bergaji NULL, sehingga COUNT(gaji)=4."},{"id":"SKB-PRAKOM-N0047","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Tabel PEGAWAI\nid | nama  | dept | gaji\n1  | Ani   | TI   | 8\n2  | Budi  | TI   | 6\n3  | Citra | HR   | 7\n4  | Dedi  | HR   | NULL\n5  | Eka   | KEU  | 9\n\nBanyak baris hasil SELECT * FROM PEGAWAI WHERE gaji > 6; adalah...","options":["A. 4 baris karena NULL dianggap lebih besar dari 6","B. 3 baris (Ani, Citra, Eka)","C. 2 baris karena hanya gaji di atas 7 yang lolos","D. 5 baris karena semua baris diperiksa tanpa filter","E. 4 baris karena NULL dianggap sama dengan nol"],"ans":1,"scores":[0,5,0,0,0],"trick":"Perbandingan dengan NULL menghasilkan UNKNOWN → baris tidak terpilih.","explanation":"Gaji 8, 7, 9 memenuhi >6 sehingga Ani, Citra, Eka terpilih. Baris NULL menghasilkan UNKNOWN dan tersaring."},{"id":"SKB-PRAKOM-N0048","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Tabel PEGAWAI\nid | nama  | dept | gaji\n1  | Ani   | TI   | 8\n2  | Budi  | TI   | 6\n3  | Citra | HR   | 7\n4  | Dedi  | HR   | NULL\n5  | Eka   | KEU  | 9\n\nSELECT dept, COUNT(*) FROM PEGAWAI GROUP BY dept HAVING COUNT(*) > 1; menghasilkan...","options":["A. TI = 2, HR = 2, dan KEU = 1","B. Hanya KEU = 1","C. TI = 2 dan HR = 2","D. TI = 2 saja karena HR memuat NULL","E. Kesalahan sintaks karena HAVING harus sebelum GROUP BY"],"ans":2,"scores":[0,0,5,0,0],"trick":"WHERE menyaring baris sebelum dikelompokkan; HAVING menyaring kelompok sesudah agregasi.","explanation":"Kelompok TI (2 baris), HR (2 baris), KEU (1 baris). HAVING COUNT(*)>1 hanya meloloskan TI dan HR."},{"id":"SKB-PRAKOM-N0049","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Tabel PEGAWAI\nid | nama  | dept | gaji\n1  | Ani   | TI   | 8\n2  | Budi  | TI   | 6\n3  | Citra | HR   | 7\n4  | Dedi  | HR   | NULL\n5  | Eka   | KEU  | 9\n\nSELECT nama FROM PEGAWAI WHERE gaji > (SELECT AVG(gaji) FROM PEGAWAI); menghasilkan...","options":["A. Ani, Citra, dan Eka","B. Hanya Eka","C. Budi dan Citra","D. Ani dan Eka","E. Ani, Budi, Citra, dan Eka"],"ans":3,"scores":[0,0,0,5,0],"trick":"Rata-rata = 7,5 → yang lebih dari 7,5: gaji 8 dan 9.","explanation":"Subquery mengembalikan 7,5. Gaji > 7,5 adalah Ani (8) dan Eka (9). Citra (7) dan Budi (6) di bawahnya, Dedi (NULL) tersaring."},{"id":"SKB-PRAKOM-N0050","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Tabel A(id) berisi 1, 2, 3 dan tabel B(id) berisi 2, 3, 3, 4. Berapa jumlah baris hasil A INNER JOIN B ON A.id = B.id?","options":["A. 2 baris karena nilai duplikat dihapus otomatis","B. 4 baris","C. 5 baris","D. 6 baris","E. 3 baris"],"ans":4,"scores":[0,0,0,0,5],"trick":"INNER JOIN menghasilkan satu baris per pasangan cocok (duplikat ikut terhitung).","explanation":"id 2 cocok sekali (1 baris), id 3 cocok dua kali (2 baris), total 3. id 1 dan 4 tidak punya pasangan."},{"id":"SKB-PRAKOM-N0051","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Dengan tabel A(id) = 1, 2, 3 dan B(id) = 2, 3, 3, 4, jumlah baris A LEFT JOIN B ON A.id = B.id adalah...","options":["A. 4 baris","B. 3 baris","C. 5 baris","D. 7 baris","E. 6 baris"],"ans":0,"scores":[5,0,0,0,0],"trick":"LEFT JOIN = semua baris kiri + yang cocok kanan (NULL bila tak cocok).","explanation":"id 1 tidak cocok (1 baris dengan NULL), id 2 satu baris, id 3 dua baris: total 4. FULL JOIN akan 5 baris karena ditambah id 4 dari B."},{"id":"SKB-PRAKOM-N0052","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Perbedaan UNION dan UNION ALL pada SQL adalah...","options":["A. UNION mempertahankan duplikat, UNION ALL menghapusnya","B. UNION menghapus baris duplikat pada hasil gabungan, UNION ALL mempertahankannya","C. UNION hanya dapat dipakai pada satu tabel, UNION ALL pada banyak tabel","D. UNION menggabungkan kolom, UNION ALL menggabungkan baris","E. UNION lebih cepat karena tidak mengurutkan, UNION ALL mengurutkan hasil"],"ans":1,"scores":[0,5,0,0,0],"trick":"UNION = distinct; UNION ALL = apa adanya (lebih cepat).","explanation":"UNION melakukan penghapusan duplikat (butuh proses tambahan), sedangkan UNION ALL langsung menggabungkan seluruh baris."},{"id":"SKB-PRAKOM-N0053","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Perintah SQL berikut yang termasuk DDL adalah...","options":["A. DELETE FROM","B. UPDATE","C. TRUNCATE TABLE","D. GRANT","E. COMMIT"],"ans":2,"scores":[0,0,5,0,0],"trick":"DDL: CREATE, ALTER, DROP, TRUNCATE. DML: SELECT, INSERT, UPDATE, DELETE. DCL: GRANT, REVOKE. TCL: COMMIT, ROLLBACK.","explanation":"TRUNCATE mengosongkan tabel dan tergolong DDL pada kebanyakan DBMS. DELETE dan UPDATE tergolong DML, GRANT adalah DCL, COMMIT adalah TCL."},{"id":"SKB-PRAKOM-N0054","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Relasi NILAI(NIP, KodeDiklat, NamaDiklat, Skor) dengan kunci utama (NIP, KodeDiklat) dan ketergantungan KodeDiklat → NamaDiklat. Relasi ini melanggar bentuk normal...","options":["A. Pertama (1NF) karena ada atribut berulang","B. Ketiga (3NF) karena ada ketergantungan transitif","C. BCNF saja, tetapi sudah memenuhi 2NF","D. Kedua (2NF) karena ada ketergantungan parsial","E. Tidak melanggar apa pun sehingga sudah normal"],"ans":3,"scores":[0,0,0,5,0],"trick":"2NF = tidak ada atribut non-kunci bergantung pada SEBAGIAN kunci utama.","explanation":"NamaDiklat hanya bergantung pada KodeDiklat (bagian dari kunci komposit) sehingga terjadi dependensi parsial. Solusi: pisahkan tabel DIKLAT(KodeDiklat, NamaDiklat)."},{"id":"SKB-PRAKOM-N0055","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Relasi PEGAWAI(NIP, Nama, KodeUnit, NamaUnit) dengan kunci utama NIP dan KodeUnit → NamaUnit. Relasi ini melanggar...","options":["A. Bentuk normal pertama karena memuat nilai majemuk","B. Bentuk normal kedua karena kunci utama bersifat komposit","C. Bentuk normal ketiga (3NF) karena ada ketergantungan transitif","D. Tidak melanggar karena NIP unik","E. Bentuk normal Boyce-Codd saja"],"ans":2,"scores":[0,0,5,0,0],"trick":"3NF = tidak ada ketergantungan transitif atribut non-kunci → non-kunci.","explanation":"NIP → KodeUnit → NamaUnit adalah ketergantungan transitif. Pisahkan UNIT(KodeUnit, NamaUnit)."},{"id":"SKB-PRAKOM-N0056","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Hubungan banyak-ke-banyak (M:N) antara PEGAWAI dan DIKLAT pada basis data relasional diimplementasikan dengan...","options":["A. Menambahkan kolom DIKLAT pada tabel PEGAWAI berisi daftar dipisah koma","B. Menjadikan kunci utama PEGAWAI sebagai kunci utama DIKLAT","C. Menggabungkan kedua tabel menjadi satu tabel tanpa kunci","D. Tabel penghubung (junction) yang memuat kunci asing kedua tabel","E. Membuat view yang menyatukan kedua tabel"],"ans":3,"scores":[0,0,0,5,0],"trick":"M:N → tabel asosiatif dengan 2 FK.","explanation":"Tabel penghubung (misal PESERTA_DIKLAT) memuat FK ke PEGAWAI dan DIKLAT; kombinasi keduanya dapat menjadi PK."},{"id":"SKB-PRAKOM-N0057","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Properti ACID yang menjamin bahwa transaksi dijalankan seluruhnya atau tidak sama sekali adalah...","options":["A. Atomicity","B. Consistency","C. Isolation","D. Durability","E. Availability"],"ans":0,"scores":[5,0,0,0,0],"trick":"A = semua atau tidak sama sekali; C = valid; I = terpisah; D = tahan permanen.","explanation":"Atomicity menjamin all-or-nothing. Durability menjamin hasil commit tetap ada walau sistem gagal."},{"id":"SKB-PRAKOM-N0058","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Tingkat isolasi transaksi minimum yang mencegah dirty read tetapi masih memungkinkan non-repeatable read adalah...","options":["A. Read Uncommitted","B. Read Committed","C. Repeatable Read","D. Serializable","E. Snapshot Kosong"],"ans":1,"scores":[0,5,0,0,0],"trick":"RU: dirty read ada | RC: dirty tidak, non-repeatable ada | RR: phantom ada | Serializable: aman.","explanation":"Read Committed hanya membaca data yang sudah di-commit sehingga mencegah dirty read, tetapi pembacaan ulang dapat berbeda."},{"id":"SKB-PRAKOM-N0059","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Strategi backup yang hanya menyalin data yang berubah sejak backup PENUH terakhir disebut...","options":["A. Incremental","B. Mirror","C. Snapshot logis","D. Archive","E. Differential"],"ans":4,"scores":[0,0,0,0,5],"trick":"Differential = sejak full terakhir; Incremental = sejak backup apa pun terakhir.","explanation":"Pemulihan differential cukup full + differential terakhir, sedangkan incremental membutuhkan full + seluruh incremental berurutan."},{"id":"SKB-PRAKOM-N0060","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Pada skema bintang (star schema) data warehouse, tabel yang menyimpan ukuran numerik transaksi dan terhubung ke banyak tabel dimensi adalah...","options":["A. Tabel dimensi","B. Tabel staging","C. Tabel referensi","D. Tabel log","E. Tabel fakta"],"ans":4,"scores":[0,0,0,0,5],"trick":"Star schema: 1 fakta di tengah + dimensi di sekelilingnya.","explanation":"Tabel fakta menyimpan ukuran (jumlah, nilai) beserta kunci asing ke tabel dimensi seperti waktu, wilayah, dan OPD."},{"id":"SKB-PRAKOM-N0061","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Jenis basis data NoSQL yang menyimpan data sebagai pasangan kunci-nilai dan biasa dipakai untuk cache adalah...","options":["A. Redis","B. MongoDB","C. Neo4j","D. Apache Cassandra","E. PostgreSQL"],"ans":0,"scores":[5,0,0,0,0],"trick":"Redis=key-value; MongoDB=document; Cassandra=wide-column; Neo4j=graph.","explanation":"Redis berbasis memori dengan model kunci-nilai. MongoDB document store, Cassandra wide-column, Neo4j graph, PostgreSQL relasional."},{"id":"SKB-PRAKOM-N0062","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Cara paling efektif mencegah SQL Injection pada aplikasi web adalah...","options":["A. Menyembunyikan pesan kesalahan basis data saja","B. Membatasi panjang kolom input menjadi 20 karakter","C. Menggunakan prepared statement/parameterized query","D. Mengganti nama tabel menjadi nama acak","E. Mengenkripsi seluruh basis data dengan AES"],"ans":2,"scores":[0,0,5,0,0],"trick":"Pisahkan kode SQL dari data input = parameterized query.","explanation":"Prepared statement memastikan input diperlakukan sebagai data, bukan bagian perintah SQL. Opsi lain hanya mengurangi dampak."},{"id":"SKB-PRAKOM-N0063","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Pada basis data, indeks (B-tree) pada kolom yang sering dipakai pada WHERE akan...","options":["A. Mempercepat seluruh operasi tulis dan baca tanpa efek samping","B. Memperlambat pencarian tetapi menghemat penyimpanan","C. Menjamin data tidak pernah duplikat pada setiap kolom","D. Mempercepat pencarian tetapi memperlambat INSERT/UPDATE dan menambah penyimpanan","E. Menggantikan kebutuhan kunci utama"],"ans":3,"scores":[0,0,0,5,0],"trick":"Index: baca cepat, tulis lebih lambat, makan ruang.","explanation":"Indeks menjaga struktur terurut sehingga pencarian/rentang lebih cepat; setiap perubahan data harus memperbarui indeks."},{"id":"SKB-PRAKOM-N0064","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Basis Data & SQL Lanjutan","q":"Kondisi dua transaksi saling menunggu kunci yang dipegang lawannya sehingga tidak ada yang dapat melanjutkan disebut...","options":["A. Dirty read","B. Deadlock","C. Phantom read","D. Rollback segment","E. Checkpoint"],"ans":1,"scores":[0,5,0,0,0],"trick":"Deadlock = saling tunggu melingkar; DBMS memilih korban untuk di-rollback.","explanation":"Deadlock terjadi karena sirkular menunggu kunci. DBMS biasanya mendeteksi dan membatalkan salah satu transaksi."},{"id":"SKB-PRAKOM-N0065","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Perhatikan kode Python berikut.\ns = 0\nfor i in range(1, 10, 2):\n    s += i\nprint(s)\nOutput program adalah...","options":["A. 20","B. 25","C. 30","D. 45","E. 16"],"ans":1,"scores":[0,5,0,0,0],"trick":"range(1,10,2) = 1,3,5,7,9.","explanation":"Penjumlahan 1+3+5+7+9 = 25. Nilai 10 tidak ikut karena batas atas eksklusif."},{"id":"SKB-PRAKOM-N0066","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Fungsi f didefinisikan: f(n) = 1 jika n ≤ 1; selain itu f(n) = f(n-1) + f(n-2). Nilai f(6) adalah...","options":["A. 8","B. 21","C. 11","D. 13","E. 10"],"ans":3,"scores":[0,0,0,5,0],"trick":"f: 1,1,2,3,5,8,13 (f(0)=f(1)=1).","explanation":"Definisi rekursif ini membentuk deret Fibonacci dengan dua nilai awal 1: f(2)=2, f(3)=3, f(4)=5, f(5)=8, sehingga f(6)=13."},{"id":"SKB-PRAKOM-N0067","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Sebuah stack kosong dijalankan operasi: push(1), push(2), push(3), pop, push(4), pop. Isi stack dari dasar ke puncak sekarang adalah...","options":["A. 1, 2, 4","B. 1, 2, 3","C. 2, 3","D. 1, 4","E. 1, 2"],"ans":4,"scores":[0,0,0,0,5],"trick":"Stack = LIFO: pop mengambil elemen terakhir yang dimasukkan.","explanation":"push 1,2,3 → [1,2,3]; pop → 3 keluar; push 4 → [1,2,4]; pop → 4 keluar → [1,2]."},{"id":"SKB-PRAKOM-N0068","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Pada pohon biner dengan akar 1, anak kiri 2 (anak 4 dan 5), anak kanan 3, urutan traversal inorder (kiri-akar-kanan) adalah...","options":["A. 1, 2, 4, 5, 3","B. 4, 5, 2, 3, 1","C. 4, 2, 5, 1, 3","D. 1, 2, 3, 4, 5","E. 4, 2, 1, 5, 3"],"ans":2,"scores":[0,0,5,0,0],"trick":"Preorder: akar-kiri-kanan; Inorder: kiri-akar-kanan; Postorder: kiri-kanan-akar.","explanation":"Subpohon kiri (2) inorder = 4,2,5. Lalu akar 1, lalu 3: 4,2,5,1,3. Preorder 1,2,4,5,3 dan postorder 4,5,2,3,1."},{"id":"SKB-PRAKOM-N0069","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Kompleksitas waktu terburuk algoritma bubble sort untuk n elemen adalah...","options":["A. O(n²)","B. O(n log n)","C. O(n)","D. O(log n)","E. O(2ⁿ)"],"ans":0,"scores":[5,0,0,0,0],"trick":"Bubble/selection/insertion = O(n²); merge/heap = O(n log n).","explanation":"Bubble sort memiliki dua loop bersarang sehingga pada kasus terburuk membandingkan sekitar n² pasangan."},{"id":"SKB-PRAKOM-N0070","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Bubble sort pada larik [5, 1, 4, 2, 8] setelah SATU kali putaran (pass) pertama menjadi...","options":["A. [1, 2, 4, 5, 8]","B. [1, 4, 5, 2, 8]","C. [5, 1, 4, 2, 8]","D. [1, 5, 4, 2, 8]","E. [1, 4, 2, 5, 8]"],"ans":4,"scores":[0,0,0,0,5],"trick":"Satu pass memindahkan elemen terbesar ke ujung.","explanation":"Perbandingan berurutan: (5,1) tukar → 1,5,4,2,8; (5,4) tukar → 1,4,5,2,8; (5,2) tukar → 1,4,2,5,8; (5,8) tidak. Hasil 1,4,2,5,8."},{"id":"SKB-PRAKOM-N0071","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Maksimum jumlah perbandingan binary search pada larik terurut berisi 100 elemen adalah sekitar...","options":["A. 100","B. 50","C. 7","D. 10","E. 14"],"ans":2,"scores":[0,0,5,0,0],"trick":"Maks langkah ≈ ⌊log₂ n⌋ + 1.","explanation":"log₂100 ≈ 6,64 sehingga ⌊6,64⌋+1 = 7 perbandingan."},{"id":"SKB-PRAKOM-N0072","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Pada JavaScript, hasil ekspresi \"5\" + 3 dan \"5\" - 3 secara berturut-turut adalah...","options":["A. 8 dan 2","B. \"53\" dan 2","C. \"53\" dan \"53\"","D. 8 dan 8","E. \"8\" dan \"2\""],"ans":1,"scores":[0,5,0,0,0],"trick":"+ dengan string = penggabungan; - memaksa angka.","explanation":"Operator + dengan salah satu operan string menggabungkan teks sehingga \"53\"; operator - mengonversi ke angka sehingga 2."},{"id":"SKB-PRAKOM-N0073","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Perhatikan kode Python.\nx = [10, 20, 30, 40, 50]\nprint(x[1:4])\nOutput-nya adalah...","options":["A. [20, 30, 40]","B. [10, 20, 30, 40]","C. [20, 30, 40, 50]","D. [10, 20, 30]","E. [30, 40]"],"ans":0,"scores":[5,0,0,0,0],"trick":"Slicing [a:b] mengambil indeks a sampai b-1.","explanation":"Indeks 1,2,3 berisi 20,30,40; indeks 4 tidak termasuk."},{"id":"SKB-PRAKOM-N0074","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Pemrograman & Logika Algoritma (Analisis Kode)","q":"Prinsip OOP yang memungkinkan objek-objek dari kelas berbeda merespons pemanggilan metode yang sama dengan perilaku berbeda adalah...","options":["A. Enkapsulasi","B. Abstraksi data","C. Pewarisan tunggal","D. Polimorfisme","E. Modularitas"],"ans":3,"scores":[0,0,0,5,0],"trick":"Poli = banyak bentuk; overriding/overloading.","explanation":"Contoh: metode hitungGaji() pada kelas PNS dan PPPK menghasilkan perhitungan yang berbeda meski dipanggil sama."},{"id":"SKB-PRAKOM-N0075","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Dalam kerangka kerja Scrum, tanggung jawab utama Product Owner adalah...","options":["A. Memastikan tim mengikuti aturan Scrum dan menghilangkan hambatan","B. Mengelola Product Backlog dan memaksimalkan nilai produk","C. Menulis seluruh kode program produk","D. Menentukan jam kerja dan gaji anggota tim","E. Memimpin Daily Scrum setiap pagi"],"ans":1,"scores":[0,5,0,0,0],"trick":"PO = apa & prioritas; SM = proses; Developers = bagaimana/bangun.","explanation":"Product Owner bertanggung jawab atas nilai produk dan keteraturan Product Backlog. Scrum Master memfasilitasi proses."},{"id":"SKB-PRAKOM-N0076","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Pada UML, relasi di mana bagian tidak dapat hidup tanpa keseluruhannya (misal Bangunan dan Ruangan) disebut...","options":["A. Agregasi","B. Asosiasi","C. Dependensi","D. Realisasi","E. Komposisi"],"ans":4,"scores":[0,0,0,0,5],"trick":"Komposisi = berlian terisi (hidup-mati bersama); Agregasi = berlian kosong.","explanation":"Dalam komposisi bagian bergantung pada siklus hidup keseluruhan. Pada agregasi bagian dapat berdiri sendiri."},{"id":"SKB-PRAKOM-N0077","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Pengujian dengan nilai batas: input usia valid 18–58 tahun. Kumpulan data uji nilai batas yang paling tepat adalah...","options":["A. 18, 30, 58","B. 0, 18, 58, 100","C. 17, 18, 19, 57, 58, 59","D. 17, 59 saja","E. 20, 40, 50"],"ans":2,"scores":[0,0,5,0,0],"trick":"BVA: uji di sekitar batas (min-1, min, min+1, max-1, max, max+1).","explanation":"Boundary Value Analysis menguji nilai tepat di batas dan di kedua sisinya untuk menemukan kesalahan operator pembanding."},{"id":"SKB-PRAKOM-N0078","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Pengujian yang dilakukan untuk memastikan perubahan kode baru tidak merusak fungsi yang sudah berjalan disebut...","options":["A. Regression testing","B. Smoke testing","C. Acceptance testing","D. Stress testing","E. Unit testing"],"ans":0,"scores":[5,0,0,0,0],"trick":"Regression = pastikan yang lama tetap jalan.","explanation":"Regression testing mengulang uji yang relevan setelah perubahan untuk memastikan tidak muncul cacat baru."},{"id":"SKB-PRAKOM-N0079","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Metode HTTP berikut yang bersifat idempoten adalah...","options":["A. POST","B. PATCH selalu","C. CONNECT acak","D. PUT","E. Tidak ada metode yang idempoten"],"ans":3,"scores":[0,0,0,5,0],"trick":"Idempoten: GET, PUT, DELETE, HEAD, OPTIONS. POST tidak.","explanation":"Memanggil PUT berulang dengan data sama menghasilkan keadaan sumber daya yang sama. POST dapat membuat banyak sumber daya baru."},{"id":"SKB-PRAKOM-N0080","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Kode status HTTP yang tepat ketika pengguna sudah terautentikasi tetapi tidak memiliki hak mengakses sumber daya adalah...","options":["A. 403 Forbidden","B. 401 Unauthorized","C. 404 Not Found","D. 400 Bad Request","E. 429 Too Many Requests"],"ans":0,"scores":[5,0,0,0,0],"trick":"401 = belum/gagal autentikasi; 403 = terautentikasi tapi tak berhak.","explanation":"Pada API yang baik 401 dipakai ketika kredensial hilang/tidak valid, 403 ketika identitas dikenali tetapi izin kurang."},{"id":"SKB-PRAKOM-N0081","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Token JWT terdiri atas tiga bagian yang dipisahkan titik, yaitu...","options":["A. Header, Body, dan Footer","B. Key, Value, dan Hash","C. Issuer, Audience, dan Password","D. Header, Payload, dan Signature","E. Salt, Cipher, dan Tag"],"ans":3,"scores":[0,0,0,5,0],"trick":"JWT = header.payload.signature (Base64URL).","explanation":"Header memuat algoritma, payload memuat klaim, signature dipakai memverifikasi integritas. JWT bukan terenkripsi secara default."},{"id":"SKB-PRAKOM-N0082","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Risiko nomor satu pada OWASP Top 10 edisi 2021 adalah...","options":["A. Injection","B. Cryptographic Failures","C. Insecure Design","D. Security Misconfiguration","E. Broken Access Control"],"ans":4,"scores":[0,0,0,0,5],"trick":"OWASP 2021: A01 Broken Access Control, A02 Cryptographic Failures, A03 Injection.","explanation":"Pada edisi 2021 Broken Access Control naik ke peringkat pertama, diikuti Cryptographic Failures dan Injection."},{"id":"SKB-PRAKOM-N0083","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Sebuah serangan menyisipkan skrip berbahaya pada kolom komentar yang dijalankan di peramban pengunjung lain. Serangan itu dikenal sebagai...","options":["A. Cross-Site Request Forgery (CSRF)","B. SQL Injection","C. Cross-Site Scripting (XSS)","D. Man-in-the-Middle","E. Buffer overflow"],"ans":2,"scores":[0,0,5,0,0],"trick":"XSS = skrip disuntik ke halaman; mitigasi: output encoding & CSP.","explanation":"XSS menyalahgunakan input yang tidak disanitasi saat ditampilkan kembali. CSRF memaksa pengguna terautentikasi mengirim permintaan yang tidak diinginkan."},{"id":"SKB-PRAKOM-N0084","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Perintah git yang setara dengan 'git fetch' diikuti 'git merge' adalah...","options":["A. git push","B. git pull","C. git clone","D. git stash","E. git rebase --abort"],"ans":1,"scores":[0,5,0,0,0],"trick":"pull = fetch + merge; fetch hanya mengambil tanpa menggabung.","explanation":"git pull mengambil perubahan dari remote lalu menggabungkannya ke cabang aktif."},{"id":"SKB-PRAKOM-N0085","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Rekayasa Perangkat Lunak & DevSecOps","q":"Praktik CI/CD yang tepat sebelum rilis aplikasi layanan publik provinsi adalah...","options":["A. Mengunggah kode langsung ke server produksi dari laptop pengembang","B. Melewati pengujian demi mengejar tenggat peluncuran","C. Menjalankan uji otomatis dan pemindaian keamanan pada pipeline sebelum deploy","D. Menyimpan kata sandi basis data di repositori kode agar mudah","E. Melakukan deploy hanya pada hari Jumat sore"],"ans":2,"scores":[0,0,5,0,0],"trick":"CI/CD sehat: build → test → scan → deploy bertahap.","explanation":"Pipeline otomatis dengan uji dan pemindaian kerentanan mengurangi risiko cacat dan kebocoran rahasia ke produksi."},{"id":"SKB-PRAKOM-N0086","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Sebuah host memiliki alamat 172.16.40.77/20. Alamat jaringan dan alamat broadcast subnet tersebut adalah...","options":["A. 172.16.32.0 dan 172.16.47.255","B. 172.16.40.0 dan 172.16.40.255","C. 172.16.32.0 dan 172.16.39.255","D. 172.16.0.0 dan 172.16.255.255","E. 172.16.40.64 dan 172.16.47.255"],"ans":0,"scores":[5,0,0,0,0],"trick":"Prefix /20 → blok oktet ketiga = 16 (256-240). 40 berada di blok 32–47.","explanation":"Mask /20 = 255.255.240.0 sehingga ukuran blok pada oktet ketiga 16. Kelipatan 16 terbesar ≤ 40 adalah 32 → jaringan 172.16.32.0, broadcast 172.16.47.255."},{"id":"SKB-PRAKOM-N0087","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Alamat 192.168.5.130/26 berada pada subnet dengan alamat broadcast...","options":["A. 192.168.5.255","B. 192.168.5.129","C. 192.168.5.192","D. 192.168.5.159","E. 192.168.5.191"],"ans":4,"scores":[0,0,0,0,5],"trick":"/26 → blok 64: 0, 64, 128, 192. 130 ada di blok 128–191.","explanation":"Subnet 192.168.5.128/26 memiliki rentang host .129–.190 dan broadcast .191."},{"id":"SKB-PRAKOM-N0088","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Empat jaringan 192.168.0.0/24, 192.168.1.0/24, 192.168.2.0/24, dan 192.168.3.0/24 dapat diringkas (route summarization) menjadi...","options":["A. 192.168.0.0/23","B. 192.168.0.0/22","C. 192.168.0.0/21","D. 192.168.0.0/24","E. 192.168.0.0/16"],"ans":1,"scores":[0,5,0,0,0],"trick":"4 blok /24 berurutan, kelipatan 4 → /22.","explanation":"Empat blok /24 = 1024 alamat = /22 (255.255.252.0), dan 0 adalah kelipatan 4 sehingga rapat dengan batas blok."},{"id":"SKB-PRAKOM-N0089","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Kantor memerlukan subnet untuk 500 host aktif. Panjang prefiks paling efisien adalah...","options":["A. /24","B. /22","C. /23","D. /25","E. /21"],"ans":2,"scores":[0,0,5,0,0],"trick":"Host usable = 2^h − 2. 2^9−2=510 ≥ 500 → h=9 → /23.","explanation":"Dengan 9 bit host tersedia 510 host usable. /24 hanya 254, sedangkan /22 (1022) memboroskan."},{"id":"SKB-PRAKOM-N0090","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Dengan blok 192.168.10.0/24 dan metode VLSM, tiga departemen memerlukan 100, 50, dan 25 host. Jika dialokasikan dari yang terbesar, alamat jaringan subnet departemen 50 host adalah...","options":["A. 192.168.10.64/26","B. 192.168.10.0/26","C. 192.168.10.128/25","D. 192.168.10.128/26","E. 192.168.10.192/26"],"ans":3,"scores":[0,0,0,5,0],"trick":"Urutkan terbesar dulu: 100→/25, 50→/26, 25→/27.","explanation":"100 host → /25 (192.168.10.0–127). 50 host → /26 mulai 192.168.10.128 (128–191). 25 host → /27 mulai 192.168.10.192."},{"id":"SKB-PRAKOM-N0091","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Wildcard mask pada ACL yang setara dengan subnet mask /27 adalah...","options":["A. 0.0.0.27","B. 0.0.0.224","C. 0.0.0.63","D. 255.255.255.224","E. 0.0.0.31"],"ans":4,"scores":[0,0,0,0,5],"trick":"Wildcard = 255.255.255.255 − subnet mask.","explanation":"Mask /27 = 255.255.255.224, sehingga wildcard = 255.255.255.255 − 255.255.255.224 = 0.0.0.31. Wildcard menandai bit yang boleh bervariasi pada ACL."},{"id":"SKB-PRAKOM-N0092","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Alamat IPv6 yang termasuk link-local unicast memiliki awalan...","options":["A. FE80::/10","B. 2001:DB8::/32","C. FC00::/7","D. ::1/128","E. FF02::/16"],"ans":0,"scores":[5,0,0,0,0],"trick":"Link-local FE80::/10; loopback ::1; ULA FC00::/7; multicast FF00::/8.","explanation":"Alamat link-local dipakai pada satu segmen jaringan dan tidak dirutekan. 2001:DB8::/32 adalah rentang dokumentasi."},{"id":"SKB-PRAKOM-N0093","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Pada protokol routing, nilai administrative distance (AD) default Cisco untuk route static adalah...","options":["A. 90","B. 1","C. 110","D. 120","E. 20"],"ans":1,"scores":[0,5,0,0,0],"trick":"AD: connected 0, static 1, eBGP 20, EIGRP 90, OSPF 110, RIP 120.","explanation":"Semakin kecil AD semakin dipercaya. Static route (1) mengalahkan OSPF (110) dan RIP (120) untuk prefiks yang sama."},{"id":"SKB-PRAKOM-N0094","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Protokol routing yang bertipe link-state dan memakai algoritma Dijkstra (SPF) adalah...","options":["A. RIP","B. BGP","C. OSPF","D. EIGRP versi lama saja","E. ARP"],"ans":2,"scores":[0,0,5,0,0],"trick":"RIP = distance vector (hop maks 15); OSPF = link-state; BGP = path vector antar-AS.","explanation":"OSPF menyebarkan LSA dan setiap router membangun topologi lengkap untuk menghitung jalur terpendek dengan SPF."},{"id":"SKB-PRAKOM-N0095","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Urutan empat pesan DHCP saat klien memperoleh alamat IP adalah...","options":["A. Request, Offer, Discover, Acknowledge","B. Offer, Discover, Acknowledge, Request","C. Discover, Request, Offer, Acknowledge","D. Discover, Offer, Request, Acknowledge","E. Hello, Offer, Request, Release"],"ans":3,"scores":[0,0,0,5,0],"trick":"Singkatan DORA: Discover-Offer-Request-Ack.","explanation":"Klien Discover (broadcast), server Offer, klien Request, server Acknowledge."},{"id":"SKB-PRAKOM-N0096","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Pada DNS, catatan (record) yang menentukan server surat elektronik suatu domain adalah...","options":["A. CNAME","B. PTR","C. MX","D. NS","E. A"],"ans":2,"scores":[0,0,5,0,0],"trick":"A: IPv4; AAAA: IPv6; CNAME: alias; MX: mail; NS: name server; PTR: reverse.","explanation":"MX (Mail Exchanger) menunjuk server penerima surat beserta prioritasnya."},{"id":"SKB-PRAKOM-N0097","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Teknologi pemisahan jaringan logis pada satu switch fisik yang memberi tag 4 byte pada frame menurut IEEE 802.1Q adalah...","options":["A. Port mirroring","B. Link aggregation","C. Spanning tree","D. VLAN trunking","E. Port forwarding"],"ans":3,"scores":[0,0,0,5,0],"trick":"802.1Q = VLAN tagging; 802.3ad = link aggregation; 802.1D = STP.","explanation":"Trunk membawa frame banyak VLAN dengan tag 802.1Q (VLAN ID 12 bit)."},{"id":"SKB-PRAKOM-N0098","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Keluaran 'traceroute' menunjukkan paket berhenti dengan tanda * * * mulai hop ke-4. Dugaan paling mungkin adalah...","options":["A. Hop ke-4 atau seterusnya memblokir/tidak membalas pesan ICMP TTL exceeded","B. Seluruh jaringan tujuan pasti mati permanen","C. Kabel di komputer asal terputus","D. DNS salah mengubah nama menjadi IP","E. Subnet mask komputer asal salah"],"ans":0,"scores":[5,0,0,0,0],"trick":"* * * = tidak ada balasan (bisa diblokir firewall), bukan bukti tujuan mati.","explanation":"Traceroute memakai TTL berurutan; hop yang tidak membalas ICMP Time Exceeded tampil sebagai *. Hal ini sering karena kebijakan firewall."},{"id":"SKB-PRAKOM-N0099","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Perangkat yang bekerja pada Layer 3 OSI dan meneruskan paket berdasarkan alamat IP adalah...","options":["A. Switch Layer 2","B. Router","C. Hub","D. Repeater","E. Access point murni"],"ans":1,"scores":[0,5,0,0,0],"trick":"L1 hub/repeater; L2 switch/bridge (MAC); L3 router (IP); L4 segment (TCP/UDP).","explanation":"Router membaca header IP untuk memilih jalur antar-jaringan. Switch L2 memakai alamat MAC."},{"id":"SKB-PRAKOM-N0100","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Jaringan Komputer Lanjutan","q":"Standar keamanan nirkabel yang memakai pertukaran kunci SAE (Simultaneous Authentication of Equals) adalah...","options":["A. WEP","B. WPA-TKIP","C. WPA2-PSK saja","D. WPS PIN","E. WPA3-Personal"],"ans":4,"scores":[0,0,0,0,5],"trick":"WEP < WPA < WPA2 < WPA3 (SAE).","explanation":"WPA3-Personal mengganti PSK dengan SAE yang tahan serangan kamus offline."},{"id":"SKB-PRAKOM-N0101","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Tiga tujuan keamanan informasi dalam triad CIA adalah...","options":["A. Keaslian, akuntabilitas, dan otorisasi","B. Kecepatan, efisiensi, dan skalabilitas","C. Autentikasi, autorisasi, dan pencatatan","D. Pencegahan, deteksi, dan pemulihan","E. Kerahasiaan, integritas, dan ketersediaan"],"ans":4,"scores":[0,0,0,0,5],"trick":"C-I-A = Confidentiality, Integrity, Availability.","explanation":"Serangan DDoS terutama mengancam ketersediaan; kebocoran data mengancam kerahasiaan; manipulasi data mengancam integritas."},{"id":"SKB-PRAKOM-N0102","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Tanda tangan digital dibuat dengan menggunakan...","options":["A. Kunci privat pengirim, diverifikasi dengan kunci publik pengirim","B. Kunci publik pengirim, diverifikasi dengan kunci privat penerima","C. Kunci simetris bersama yang dikirim lewat surel","D. Kunci privat penerima, diverifikasi kunci publik penerima","E. Hash tanpa kunci apa pun"],"ans":0,"scores":[5,0,0,0,0],"trick":"Tanda tangan: PRIVAT pengirim. Enkripsi kerahasiaan: PUBLIK penerima.","explanation":"Penandatangan mengenkripsi hash dokumen dengan kunci privat; siapa pun dapat memverifikasi memakai kunci publiknya sehingga terjamin keaslian dan nir-penyangkalan."},{"id":"SKB-PRAKOM-N0103","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Algoritma berikut yang tergolong enkripsi simetris adalah...","options":["A. RSA","B. ECC","C. AES","D. Diffie-Hellman","E. DSA"],"ans":2,"scores":[0,0,5,0,0],"trick":"Simetris: AES, 3DES, ChaCha20. Asimetris: RSA, ECC, DSA.","explanation":"AES memakai satu kunci yang sama untuk enkripsi dan dekripsi dan lebih cepat daripada algoritma asimetris."},{"id":"SKB-PRAKOM-N0104","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Fungsi hash seperti SHA-256 bersifat...","options":["A. Dua arah sehingga dapat didekripsi dengan kunci","B. Menghasilkan keluaran dengan panjang sama dengan panjang input","C. Hanya dapat dipakai untuk enkripsi pesan rahasia","D. Satu arah dan menghasilkan keluaran panjang tetap","E. Selalu menghasilkan nilai acak berbeda untuk input sama"],"ans":3,"scores":[0,0,0,5,0],"trick":"Hash ≠ enkripsi: tak dapat dibalik, output tetap, deterministik.","explanation":"SHA-256 selalu menghasilkan 256 bit. Input sama menghasilkan hash sama, dan sulit mencari input dari hash."},{"id":"SKB-PRAKOM-N0105","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Penyimpanan kata sandi pengguna yang paling aman pada basis data aplikasi adalah...","options":["A. Teks asli agar mudah dipulihkan","B. Hash kuat dengan salt (misal bcrypt/Argon2)","C. Dienkripsi AES dengan kunci yang disimpan di tabel yang sama","D. Disimpan sebagai MD5 tanpa salt","E. Disimpan sebagai Base64"],"ans":1,"scores":[0,5,0,0,0],"trick":"Password: hash lambat + salt, bukan enkripsi / Base64.","explanation":"Salt mencegah serangan rainbow table dan algoritma lambat memperlambat brute force. Base64 hanya pengkodean."},{"id":"SKB-PRAKOM-N0106","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Pesan dari 'bagian IT' meminta pegawai segera memasukkan kata sandi pada tautan yang tampak resmi. Serangan ini disebut...","options":["A. Brute force","B. Phishing","C. Buffer overflow","D. Port scanning","E. Session hijacking"],"ans":1,"scores":[0,5,0,0,0],"trick":"Phishing = rekayasa sosial via pesan palsu.","explanation":"Pelaku menyamar sebagai pihak tepercaya. Tindakan tepat: jangan klik, laporkan ke tim keamanan, aktifkan MFA."},{"id":"SKB-PRAKOM-N0107","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Mitigasi paling efektif terhadap dampak ransomware pada server dinas adalah...","options":["A. Membayar tebusan sesegera mungkin","B. Menonaktifkan seluruh pembaruan sistem","C. Menyimpan backup pada folder yang sama dan selalu terpasang","D. Backup 3-2-1 dengan salinan offline/immutable yang rutin diuji pemulihannya","E. Mengandalkan antivirus sebagai satu-satunya perlindungan"],"ans":3,"scores":[0,0,0,5,0],"trick":"3-2-1: 3 salinan, 2 media, 1 di luar lokasi (plus offline).","explanation":"Backup yang terputus dari jaringan dan diuji memungkinkan pemulihan tanpa tebusan. Membayar tidak menjamin data kembali."},{"id":"SKB-PRAKOM-N0108","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Pada model Zero Trust, prinsip utamanya adalah...","options":["A. Percayai semua perangkat di dalam jaringan internal","B. Cukup verifikasi sekali saat login pertama","C. Blokir seluruh akses eksternal tanpa pengecualian","D. Mengandalkan perimeter firewall sebagai satu-satunya pertahanan","E. Never trust, always verify untuk setiap permintaan akses"],"ans":4,"scores":[0,0,0,0,5],"trick":"Zero Trust: verifikasi eksplisit, least privilege, anggap sudah bocor.","explanation":"Akses dinilai kontinu berdasarkan identitas, perangkat, dan konteks, tanpa asumsi jaringan internal aman."},{"id":"SKB-PRAKOM-N0109","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Perbedaan IDS dan IPS adalah...","options":["A. IDS memblokir, IPS hanya mencatat log","B. IDS bekerja di layer aplikasi saja, IPS di layer fisik saja","C. IDS mendeteksi dan memberi peringatan, IPS dapat memblokir lalu lintas berbahaya secara aktif","D. Keduanya identik hanya beda merek","E. IDS hanya untuk jaringan nirkabel, IPS untuk kabel"],"ans":2,"scores":[0,0,5,0,0],"trick":"IDS = alarm; IPS = alarm + penutup pintu (inline).","explanation":"IPS ditempatkan inline sehingga dapat drop paket; IDS umumnya pasif (mirror/SPAN)."},{"id":"SKB-PRAKOM-N0110","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Urutan fase penanganan insiden menurut NIST SP 800-61 adalah...","options":["A. Persiapan; deteksi & analisis; containment, eradication & recovery; aktivitas pascainsiden","B. Deteksi; recovery; persiapan; laporan","C. Containment; deteksi; persiapan; eradication","D. Persiapan; eradication; deteksi; evaluasi","E. Analisis; persiapan; recovery; containment"],"ans":0,"scores":[5,0,0,0,0],"trick":"NIST IR: Preparation → Detection/Analysis → Containment/Eradication/Recovery → Post-incident.","explanation":"Empat fase tersebut membentuk siklus; pelajaran dari fase terakhir memperbaiki persiapan berikutnya."},{"id":"SKB-PRAKOM-N0111","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Dalam forensik digital, 'chain of custody' bertujuan...","options":["A. Mempercepat proses penyalinan data","B. Mengenkripsi barang bukti secara otomatis","C. Menghapus data yang tidak relevan","D. Menentukan pelaku tanpa analisis lanjut","E. Mendokumentasikan siapa memegang barang bukti dan kapan agar keabsahan tetap terjaga"],"ans":4,"scores":[0,0,0,0,5],"trick":"Chain of custody = jejak penguasaan bukti.","explanation":"Dokumentasi yang rapi menjaga integritas dan dapat diterima untuk proses hukum."},{"id":"SKB-PRAKOM-N0112","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Prinsip pemberian hak akses minimum yang diperlukan untuk menjalankan tugas dikenal sebagai...","options":["A. Separation of duties","B. Defense in depth","C. Least privilege","D. Security by obscurity","E. Fail open"],"ans":2,"scores":[0,0,5,0,0],"trick":"Least privilege = hak seperlunya; SoD = tugas dipisah.","explanation":"Least privilege mengurangi dampak akun yang disalahgunakan. Separation of duties memisahkan tugas kritis antar-orang."},{"id":"SKB-PRAKOM-N0113","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Keamanan Informasi & Siber","q":"Faktor autentikasi 'something you have' adalah...","options":["A. Kata sandi","B. Token OTP/kartu pintar","C. Sidik jari","D. Pola tekan tombol (keystroke)","E. Pertanyaan keamanan"],"ans":1,"scores":[0,5,0,0,0],"trick":"Know = sandi; Have = token; Are = biometrik.","explanation":"MFA yang kuat memadukan minimal dua kategori berbeda."},{"id":"SKB-PRAKOM-N0114","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Perintah Linux chmod 640 berkas.txt memberi izin...","options":["A. Pemilik baca-tulis, grup baca, lainnya tanpa akses","B. Pemilik baca-tulis-eksekusi, grup baca-eksekusi, lainnya baca","C. Pemilik baca, grup baca-tulis, lainnya tanpa akses","D. Semua pengguna baca-tulis","E. Pemilik tanpa akses, grup baca-tulis"],"ans":0,"scores":[5,0,0,0,0],"trick":"r=4 w=2 x=1. 6=rw-, 4=r--, 0=---.","explanation":"Angka 640 berarti rw-r-----. Pemilik dapat membaca dan menulis, grup hanya membaca, lainnya tidak punya hak."},{"id":"SKB-PRAKOM-N0115","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Entri cron '30 2 * * 1' menjalankan tugas...","options":["A. Setiap hari pukul 02.30","B. Setiap tanggal 2 pukul 01.30","C. Setiap 30 menit pada hari Senin","D. Setiap Senin pukul 02.30","E. Setiap Minggu pukul 02.30"],"ans":3,"scores":[0,0,0,5,0],"trick":"Cron: menit jam tgl bulan hari-minggu (0/7=Minggu, 1=Senin).","explanation":"Menit 30, jam 2, setiap tanggal dan bulan, hari ke-1 dalam minggu (Senin)."},{"id":"SKB-PRAKOM-N0116","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Empat disk masing-masing 2 TB disusun RAID 5. Kapasitas usable dan toleransi kegagalan disk adalah...","options":["A. 8 TB dan 2 disk","B. 6 TB dan 1 disk","C. 4 TB dan 2 disk","D. 6 TB dan 2 disk","E. 2 TB dan 3 disk"],"ans":1,"scores":[0,5,0,0,0],"trick":"RAID5: (n−1)×kapasitas, toleransi 1. RAID6: (n−2), toleransi 2. RAID10: n/2.","explanation":"RAID 5 menyimpan satu disk setara paritas terdistribusi sehingga kapasitas (4−1)×2 = 6 TB."},{"id":"SKB-PRAKOM-N0117","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Empat disk masing-masing 2 TB disusun RAID 10. Kapasitas usable adalah...","options":["A. 8 TB","B. 6 TB","C. 2 TB","D. 3 TB","E. 4 TB"],"ans":4,"scores":[0,0,0,0,5],"trick":"RAID10 = mirror lalu stripe, kapasitas separuh.","explanation":"RAID 10 membutuhkan minimal empat disk dan menyediakan n/2 kapasitas = 4 TB dengan performa tulis baik."},{"id":"SKB-PRAKOM-N0118","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Layanan dengan ketersediaan 99,9% dalam setahun (365 hari) diperkirakan mengalami downtime maksimal sekitar...","options":["A. 52,56 menit","B. 87,6 jam","C. 8,76 jam","D. 4,38 jam","E. 3,65 hari"],"ans":2,"scores":[0,0,5,0,0],"trick":"Downtime = (1 − A) × 8760 jam.","explanation":"0,1% × 8.760 jam = 8,76 jam. 99,99% ≈ 52,56 menit."},{"id":"SKB-PRAKOM-N0119","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Model layanan cloud tempat pengguna menyewa mesin virtual, jaringan, dan penyimpanan tetapi mengelola sendiri sistem operasinya adalah...","options":["A. IaaS","B. PaaS","C. SaaS","D. FaaS saja","E. DaaS saja"],"ans":0,"scores":[5,0,0,0,0],"trick":"IaaS=infrastruktur; PaaS=platform; SaaS=aplikasi jadi.","explanation":"Pada IaaS penyedia mengelola perangkat keras dan virtualisasi, pelanggan mengelola OS dan aplikasi."},{"id":"SKB-PRAKOM-N0120","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Perbedaan utama kontainer (Docker) dibanding mesin virtual adalah...","options":["A. Kontainer membutuhkan OS tamu lengkap untuk tiap instans","B. Kontainer tidak dapat dijalankan di server Linux","C. Kontainer selalu lebih lambat tetapi lebih aman","D. Kontainer berbagi kernel OS host sehingga lebih ringan dan cepat dijalankan","E. Kontainer hanya untuk basis data"],"ans":3,"scores":[0,0,0,5,0],"trick":"VM = OS tamu penuh; Container = isolasi proses berbagi kernel.","explanation":"Kontainer mengemas aplikasi beserta dependensinya dan berbagi kernel host sehingga lebih hemat sumber daya."},{"id":"SKB-PRAKOM-N0121","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Perintah Linux untuk melihat penggunaan ruang disk setiap sistem berkas dalam format mudah dibaca adalah...","options":["A. df -h","B. du -s /","C. ls -l","D. top","E. free -m"],"ans":0,"scores":[5,0,0,0,0],"trick":"df = disk free (per filesystem); du = disk usage (per folder); free = memori.","explanation":"df -h menampilkan ukuran, terpakai, dan tersedia per partisi dalam satuan K/M/G."},{"id":"SKB-PRAKOM-N0122","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Pada tata kelola pusat data, Uptime Institute Tier III menjamin...","options":["A. Tanpa redundansi apa pun, ketersediaan 99,671%","B. Toleran kegagalan penuh dengan ketersediaan 99,995%","C. Redundansi hanya pada UPS, ketersediaan 99,741%","D. Konkuren dapat dipelihara (concurrently maintainable) dengan ketersediaan sekitar 99,982%","E. Tidak ada standar tier untuk pusat data"],"ans":3,"scores":[0,0,0,5,0],"trick":"Tier I 99,671% | II 99,741% | III 99,982% | IV 99,995%.","explanation":"Tier III dapat dilakukan perawatan komponen tanpa menghentikan operasi (N+1 dengan jalur ganda)."},{"id":"SKB-PRAKOM-N0123","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Infrastruktur TI, Server & Cloud","q":"Pemulihan bencana yang menjaga sistem cadangan siap aktif dengan data tereplikasi hampir real-time disebut...","options":["A. Cold site","B. Warm site berbasis tape","C. Remote office","D. Offline archive","E. Hot site"],"ans":4,"scores":[0,0,0,0,5],"trick":"Hot = siap segera; Warm = sebagian siap; Cold = ruang kosong.","explanation":"Hot site berbiaya tinggi tetapi RTO/RPO sangat kecil, cocok untuk layanan kritis."},{"id":"SKB-PRAKOM-N0124","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Sistem Informasi, Multimedia, SIG & Data","q":"Format data geospasial yang menyimpan fitur sebagai titik, garis, dan poligon dengan atribut disebut data...","options":["A. Raster","B. Bitmap","C. Vektor","D. Hash","E. Tabular murni"],"ans":2,"scores":[0,0,5,0,0],"trick":"Vektor: titik/garis/poligon; raster: grid piksel (citra satelit, DEM).","explanation":"Batas kabupaten, jalan, dan titik sekolah umumnya vektor; citra satelit dan peta elevasi adalah raster."},{"id":"SKB-PRAKOM-N0125","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Sistem Informasi, Multimedia, SIG & Data","q":"Sistem referensi koordinat geografis global yang umum dipakai GPS dengan kode EPSG:4326 adalah...","options":["A. UTM Zona 50S","B. WGS 84","C. Bessel 1841","D. Google Mercator (EPSG:3857)","E. DGN95"],"ans":1,"scores":[0,5,0,0,0],"trick":"EPSG:4326 = WGS84 lat/long derajat; 3857 = Web Mercator.","explanation":"Koordinat lintang-bujur derajat WGS 84 dipakai GPS; UTM adalah proyeksi metrik per zona."},{"id":"SKB-PRAKOM-N0126","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Sistem Informasi, Multimedia, SIG & Data","q":"Layanan OGC yang mengirim data fitur vektor (bukan sekadar gambar peta) dapat diambil melalui...","options":["A. WMS","B. WMTS","C. WFS","D. KML saja","E. TMS"],"ans":2,"scores":[0,0,5,0,0],"trick":"WMS = gambar peta; WFS = fitur vektor; WCS = coverage raster.","explanation":"WFS memungkinkan klien meminta dan menganalisis atribut fitur, sedangkan WMS mengembalikan citra render."},{"id":"SKB-PRAKOM-N0127","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Sistem Informasi, Multimedia, SIG & Data","q":"Format gambar yang menggunakan kompresi lossless dan mendukung transparansi adalah...","options":["A. JPEG","B. PNG","C. MP3","D. BMP terkompresi lossy","E. H.264"],"ans":1,"scores":[0,5,0,0,0],"trick":"Lossy: JPEG, MP3, H.264. Lossless: PNG, FLAC, ZIP.","explanation":"PNG mempertahankan semua piksel dan mendukung kanal alfa; JPEG membuang detail untuk ukuran kecil."},{"id":"SKB-PRAKOM-N0128","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Sistem Informasi, Multimedia, SIG & Data","q":"Ukuran gambar tanpa kompresi 1920×1080 piksel dengan 24 bit warna adalah sekitar...","options":["A. 2,1 MB","B. 24 MB","C. 1,5 MB","D. 6,2 MB","E. 62 MB"],"ans":3,"scores":[0,0,0,5,0],"trick":"Ukuran = lebar × tinggi × bit / 8.","explanation":"24 bit = 3 byte per piksel: 1920 × 1080 × 3 = 6.220.800 byte ≈ 6,2 MB. Kompresi seperti JPEG/PNG akan memperkecilnya."},{"id":"SKB-PRAKOM-N0129","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Sistem Informasi, Multimedia, SIG & Data","q":"Sebuah model klasifikasi memprediksi 50 kasus positif, 40 di antaranya benar. Dari 80 kasus positif nyata. Nilai precision dan recall adalah...","options":["A. precision 0,50 dan recall 0,80","B. precision 0,80 dan recall 0,80","C. precision 0,50 dan recall 0,50","D. precision 0,40 dan recall 0,80","E. precision 0,80 dan recall 0,50"],"ans":4,"scores":[0,0,0,0,5],"trick":"Precision = TP/(TP+FP) ; Recall = TP/(TP+FN).","explanation":"TP=40, FP=10 → precision 40/50=0,8. FN=40 → recall 40/80=0,5."},{"id":"SKB-PRAKOM-N0130","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Sistem Informasi, Multimedia, SIG & Data","q":"Jenis sistem informasi yang membantu manajemen menengah dengan laporan ringkasan rutin berdasarkan data transaksi adalah...","options":["A. MIS (Management Information System)","B. TPS","C. DSS","D. EIS","E. ERP saja"],"ans":0,"scores":[5,0,0,0,0],"trick":"TPS=transaksi; MIS=laporan rutin; DSS=analisis keputusan; EIS=eksekutif.","explanation":"MIS mengolah data TPS menjadi laporan manajerial terstruktur."},{"id":"SKB-PRAKOM-N0131","examType":"SKB_PRAKOM","category":"SKB PRANATA KOMPUTER","sub":"Sistem Informasi, Multimedia, SIG & Data","q":"Kondisi model machine learning yang sangat baik pada data latih tetapi buruk pada data baru disebut...","options":["A. Overfitting","B. Underfitting","C. Normalisasi","D. Regularisasi data","E. Konvergensi"],"ans":0,"scores":[5,0,0,0,0],"trick":"Overfitting = menghafal data latih.","explanation":"Solusi: regularisasi, lebih banyak data, validasi silang, dan penyederhanaan model."}]});
